        view.nativeView.off(ViewBase.disposeNativeViewEvent, disposeCallback);
        view.nativeView.on(ViewBase.disposeNativeViewEvent, disposeCallback);
        frame.navigate({
            ...options,
            create: () => view.nativeView,
        });
        return view.nativeView;
